SELECT *
FROM TB_META_ETC_DATA_FILE_LOG AS LOG
WHERE LOG.USE_YN = 'Y'
  AND LOG.DEL_YN = 'N'
  AND LOG.MODEL_SEQ = #{etcModelSeq}
  AND DATE_FORMAT(LOG.REG_DT, '%Y-%m') = #{dateStr};

SELECT *
FROM TB_META_DATA_FILE_LOG AS LOG
